export const QUESTIONS = [
  // ───────── Företräde & regler ─────────
  { id: "r1", cat: "regler", q: "Du kommer till en korsning utan vägmärken eller trafikljus. Ett fordon kommer från höger. Vad gäller?", opts: ["Du kör först eftersom du är på större väg", "Du ska lämna företräde åt fordonet från höger", "Den som kommer först till korsningen kör först", "Ni blinkar och kommer överens"], a: 1, why: "Högerregeln: i en korsning utan skyltar eller ljus har du väjningsplikt mot fordon som kommer från höger." },
  { id: "r2", cat: "regler", q: "Vad betyder det att ha väjningsplikt?", opts: ["Du måste alltid stanna helt", "Du ska anpassa farten och stanna vid behov så att du inte hindrar andra", "Du ska tuta för att varna", "Du får köra först om du blinkar"], a: 1, why: "Väjningsplikt betyder att du i god tid ska sänka farten eller stanna så att den du ska lämna företräde inte behöver ändra fart eller riktning." },
  { id: "r3", cat: "regler", q: "En gående är på väg ut på ett obevakat övergångsställe. Vad ska du göra?", opts: ["Fortsätta, du har grönt", "Tuta så att hen ser dig", "Stanna och låta hen gå över", "Köra runt hen"], a: 2, why: "Du har väjningsplikt mot gående som är på väg ut på eller befinner sig på ett obevakat övergångsställe." },
  { id: "r4", cat: "regler", q: "Du ska köra in i en cirkulationsplats (rondell) med skylt för väjningsplikt. Vem har företräde?", opts: ["Du som kör in", "Fordon som redan kör i cirkulationen", "Den som är störst", "Den som kommer från höger utanför rondellen"], a: 1, why: "Vid rondeller är det oftast väjningsplikt vid infarten – du ska släppa fram dem som redan kör i rondellen." },
  { id: "r5", cat: "regler", q: "Hur ska du blinka när du lämnar en cirkulationsplats?", opts: ["Vänster", "Höger", "Inte alls", "Varningsblinkers"], a: 1, why: "Du blinkar höger när du ska lämna rondellen, så att andra ser att du kör ut." },
  { id: "r6", cat: "regler", q: "En buss med blinkers vill lämna en hållplats i tätort där högsta tillåtna hastighet är 50 km/h. Vad gäller?", opts: ["Bussen ska vänta tills det är tomt", "Du ska sänka farten och låta bussen köra ut", "Du ska köra om bussen", "Inget särskilt"], a: 1, why: "På vägar med högst 50 km/h ska du sakta in eller stanna för att släppa ut en buss som blinkar från en hållplats." },
  { id: "r7", cat: "regler", q: "Ett utryckningsfordon med blåljus och siren kommer bakifrån. Vad gör du?", opts: ["Ökar farten", "Stannar mitt i körfältet", "Lämnar fri väg, t.ex. kör åt sidan när det är säkert", "Ignorerar det"], a: 2, why: "Du ska lämna fri väg för utryckningsfordon. Kör åt sidan lugnt och säkert – gärna utan tvärnit." },
  { id: "r8", cat: "regler", q: "Vad betyder en heldragen mittlinje?", opts: ["Den får korsas vid omkörning", "Den får inte korsas eller överskridas", "Den visar en cykelbana", "Den betyder att du har företräde"], a: 1, why: "En heldragen linje (spärrlinje) får du inte korsa eller köra över." },
  { id: "r9", cat: "regler", q: "Trafikljuset slår om till gult när du närmar dig. Vad gäller?", opts: ["Gasa för att hinna", "Stanna om du kan göra det säkert", "Gult betyder samma som grönt", "Tuta och kör"], a: 1, why: "Gult betyder stopp – men om du är så nära att du inte kan stanna säkert får du fortsätta." },
  { id: "r10", cat: "regler", q: "Du kör ut från en parkeringsplats eller gårdsplan ut på vägen. Vad gäller?", opts: ["Högerregeln gäller", "Du har väjningsplikt mot alla på vägen", "Du har alltid företräde", "Endast mot bilar"], a: 1, why: "Den som kör ut från t.ex. parkering, gårdsplan, bensinstation eller gång- och cykelbana har väjningsplikt mot all trafik på vägen." },
  { id: "r11", cat: "regler", q: "Vilket avstånd gäller för parkering före ett övergångsställe?", opts: ["Det får du alltid göra", "Inte på eller inom 10 meter före övergångsstället", "Inom 2 meter är okej", "Bara förbjudet på natten"], a: 1, why: "Du får inte stanna eller parkera på ett övergångsställe eller närmare än 10 meter före det. Gående och förare måste kunna se varandra." },
  { id: "r12", cat: "regler", q: "Du kommer till en korsning där en spårvagn också ska köra. Inga trafikljus eller skyltar säger något annat. Vem kör först?", opts: ["Du, om du kommer från höger", "Den som kommer först", "Spårvagnen har företräde", "Den som kör fortast"], a: 2, why: "Om inga trafikljus eller skyltar säger annat ska du släppa fram spårvagnen. Den kan inte svänga undan och har lång bromssträcka." },
  { id: "r13", cat: "regler", q: "Du närmar dig en obevakad cykelöverfart. En cyklist är på väg ut på den. Vad gäller?", opts: ["Cyklisten ska alltid stanna för bilar", "Du ska anpassa farten så att cyklisten kan cykla över säkert", "Du tutar så att cyklisten väntar", "Du ökar farten för att hinna före"], a: 1, why: "Vid en obevakad cykelöverfart ska du hålla en så låg fart att cyklister kan korsa utan fara." },
  { id: "r14", cat: "regler", q: "Du kör ut från ett gångfartsområde ut på en vanlig gata. Vad gäller?", opts: ["Högerregeln gäller", "Du har företräde eftersom du kör ut", "Du har väjningsplikt mot trafiken på gatan", "Bara gående ska släppas fram"], a: 2, why: "Den som kör ut från ett gångfartsområde har väjningsplikt mot alla på vägen – precis som från en parkering." },
  { id: "r15", cat: "regler", q: "Du ska svänga vänster i en korsning. En bil möter dig och ska köra rakt fram. Vem kör först?", opts: ["Du, eftersom du blinkar", "Den som är först i korsningen", "Den som har störst bil", "Den mötande bilen"], a: 3, why: "När du svänger vänster har du väjningsplikt mot mötande trafik." },
  { id: "r16", cat: "regler", q: "Du svänger höger i en korsning. En gående går över gatan som du svänger in på. Vad gör du?", opts: ["Kör före, du har grön signal", "Tutar så att hen skyndar sig", "Stannar och låter hen gå över", "Kör runt hen"], a: 2, why: "När du svänger ska du lämna företräde åt gående som går över den gata du svänger in på." },
  { id: "r17", cat: "regler", q: "Två körfält blir till ett och trafiken går långsamt. Hur fungerar blixtlåsprincipen?", opts: ["Bilarna i vänster körfält kör alltid först", "Den som har bråttom kör först", "Bilarna turas om – en från varje körfält", "Alla stannar och väntar"], a: 2, why: "Blixtlåsprincipen betyder att man turas om, en bil i taget från varje körfält. Det gör att trafiken flyter bättre." },
  { id: "r18", cat: "regler", q: "Du vill byta körfält. En bil finns redan i körfältet bredvid. Vem har företräde?", opts: ["Du, om du blinkar", "Den som kör fortast", "Ingen – ni får bestämma", "Bilen som redan är i körfältet"], a: 3, why: "Den som byter körfält har väjningsplikt mot fordon som redan kör i det andra körfältet. Blinka i god tid och titta i döda vinkeln." },
  { id: "r19", cat: "regler", q: "Var är det förbjudet att köra om?", opts: ["På en lång rak väg med god sikt", "På en väg med streckad mittlinje", "På en motorväg", "Strax före och på ett obevakat övergångsställe"], a: 3, why: "Du får inte köra om strax före eller på ett obevakat övergångsställe. Någon kan vara på väg ut bakom bilen du kör om." },
  { id: "r20", cat: "regler", q: "När får du köra om en bil på höger sida?", opts: ["När bilen framför svänger vänster eller har ställt sig för att svänga vänster", "Aldrig", "När du har bråttom", "När bilen framför kör långsamt"], a: 0, why: "Normalt kör du om till vänster. Men ett fordon som svänger vänster, eller har ställt sig för det, ska du köra om till höger." },
  { id: "r21", cat: "regler", q: "En bil kör om dig. Vad ska du göra?", opts: ["Öka farten", "Bromsa hårt", "Köra mot mitten av vägen", "Hålla till höger och inte öka farten"], a: 3, why: "Den som blir omkörd får inte öka farten. Håll till höger så blir omkörningen snabb och säker." },
  { id: "r22", cat: "regler", q: "Trafikljuset blinkar gult. Vad betyder det?", opts: ["Var extra försiktig", "Stopp", "Kör fort förbi", "Ljuset är trasigt och du får göra som du vill"], a: 0, why: "Blinkande gult betyder att du ska vara extra försiktig. Följ vägmärken och vanliga regler, till exempel högerregeln." },
  { id: "r23", cat: "regler", q: "Trafikljuset visar grönt, men det lyser en röd pil åt vänster. Du ska svänga vänster. Vad gör du?", opts: ["Stannar – den röda pilen gäller för dig som svänger vänster", "Svänger, eftersom det är grönt", "Svänger om ingen kommer", "Blinkar höger i stället"], a: 0, why: "En pilsignal gäller för trafik i pilens riktning. Röd pil betyder stopp för dig som ska svänga dit." },
  { id: "r24", cat: "regler", q: "En polis dirigerar trafiken i en korsning med trafikljus. Vad ska du följa?", opts: ["Trafikljusen", "Vägmärkena", "Högerregeln", "Polisens tecken"], a: 3, why: "Polisens tecken går före trafikljus, vägmärken och vanliga trafikregler." },
  { id: "r25", cat: "regler", q: "En polis står i korsningen och håller ena armen rakt upp. Vad betyder det?", opts: ["Stopp för alla som närmar sig korsningen", "Kör fortare", "Svängning tillåten", "Parkering tillåten"], a: 0, why: "En arm rakt upp betyder stopp för alla som kommer mot korsningen. Den som redan är ute i korsningen får köra vidare." },
  { id: "r26", cat: "regler", q: "Vilka får INTE färdas på en motorväg?", opts: ["Personbilar", "Gående, cyklister och mopedister", "Bussar", "Lastbilar"], a: 1, why: "Motorvägen är bara för snabba motorfordon. Gående, cyklister och mopeder får inte vara där." },
  { id: "r27", cat: "regler", q: "Du kör på påfarten till en motorväg. Vad gäller?", opts: ["Du har väjningsplikt mot trafiken på motorvägen och ska anpassa farten till den", "Du har företräde och kör rakt ut", "Du stannar alltid i slutet av påfarten", "Bilarna på motorvägen måste stanna för dig"], a: 0, why: "Du byter körfält när du kör ut på motorvägen. Öka farten i accelerationsfältet och släpp fram trafiken som redan är där." },
  { id: "r28", cat: "regler", q: "Du har missat din avfart på motorvägen. Vad gör du?", opts: ["Kör vidare till nästa avfart", "Backar på vägrenen", "Vänder i en öppning i mitten", "Stannar och väntar"], a: 0, why: "Det är förbjudet att vända och backa på motorväg. Kör lugnt till nästa avfart." },
  { id: "r29", cat: "regler", q: "Hur nära en plankorsning (där vägen korsar järnväg) får du parkera?", opts: ["Inte närmare än 5 meter", "Hur nära som helst", "Inte närmare än 30 meter", "Inte närmare än 2 meter"], a: 2, why: "Du får inte parkera närmare än 30 meter från en plankorsning. Bilen får inte skymma sikten för andra." },
  { id: "r30", cat: "regler", q: "På vilken sida av vägen ska du normalt stanna eller parkera?", opts: ["Vänster sida", "Mitt på vägen", "Vilken sida som helst", "Höger sida i färdriktningen"], a: 3, why: "Du ska stanna och parkera på höger sida. På en enkelriktad väg får du också använda vänster sida." },
  { id: "r31", cat: "regler", q: "Får du parkera 5 meter från en vägkorsning?", opts: ["Ja, alltid", "Ja, om du har varningsblinkers på", "Ja, men bara på natten", "Nej, du får inte stanna eller parkera närmare än 10 meter från korsande körbana"], a: 3, why: "Inom 10 meter från en korsning får du inte stanna eller parkera. Annars skymmer bilen sikten i korsningen." },
  { id: "r32", cat: "regler", q: "Trafikljuset visar rött och gult samtidigt. Vad betyder det?", opts: ["Kör nu", "Ljuset är trasigt", "Stanna kvar – snart blir det grönt", "Bara bussar får köra"], a: 2, why: "Rött och gult tillsammans betyder att det snart blir grönt. Du får inte köra förrän det är grönt." },

  // ───────── Vägmärken ─────────
  { id: "s1", cat: "skyltar", sign: "vajningsplikt", q: "Vad betyder det här märket?", opts: ["Stopplikt", "Väjningsplikt", "Huvudled", "Varning för korsning"], a: 1, why: "En triangel med spetsen nedåt och röd kant betyder väjningsplikt." },
  { id: "s2", cat: "skyltar", sign: "stopp", q: "Vad måste du göra vid det här märket?", opts: ["Sakta in", "Stanna helt vid stopplinjen och sedan lämna företräde", "Stanna bara om det kommer bilar", "Tuta"], a: 1, why: "Stopplikt: du måste alltid stanna helt – även om vägen är tom – och sedan väja för trafiken." },
  { id: "s3", cat: "skyltar", sign: "huvudled", q: "Vad betyder märket?", opts: ["Huvudled – trafik från anslutande vägar har väjningsplikt mot dig", "Varning för gul väg", "Parkering", "Motorväg"], a: 0, why: "Gul romb = huvudled. Den som kommer från en anslutande väg ska väja för dig." },
  { id: "s4", cat: "skyltar", sign: "huvudledUpphor", q: "Vad betyder märket?", opts: ["Huvudled börjar", "Huvudled upphör – vanliga regler (t.ex. högerregeln) kan gälla igen", "Förbud mot gul bil", "Slut på parkering"], a: 1, why: "Ett snett streck över romben betyder att huvudleden upphör." },
  { id: "s5", cat: "skyltar", sign: "alg", q: "Vad varnar märket för?", opts: ["Hästar", "Älg", "Kor", "Ren"], a: 1, why: "Varning för älg. Var extra uppmärksam i skymning och gryning!" },
  { id: "s6", cat: "skyltar", sign: "barn", q: "Vad betyder märket?", opts: ["Övergångsställe", "Varning för barn", "Gångfartsområde", "Lekplats – parkering förbjuden"], a: 1, why: "Gul triangel med barn = varning för barn, t.ex. nära skola eller lekplats." },
  { id: "s7", cat: "skyltar", sign: "forbudInfart", q: "Vad betyder märket?", opts: ["Stopplikt", "Förbud mot infart med fordon", "Enkelriktad väg börjar", "Vägen är avstängd för gående"], a: 1, why: "Rött runt märke med vit balk = förbud mot infart. Du får inte köra in där." },
  { id: "s8", cat: "skyltar", sign: "parkeringsforbud", q: "Vad betyder märket?", opts: ["Stannandeförbud", "Parkeringsförbud", "Förbud mot omkörning", "Slut på förbud"], a: 1, why: "Ett snedstreck = parkeringsförbud. Du får stanna kort (t.ex. släppa av någon) men inte parkera." },
  { id: "s9", cat: "skyltar", sign: "stannandeforbud", q: "Vad betyder märket?", opts: ["Parkeringsförbud", "Stannandeförbud – du får inte stanna alls (utom i trafiken)", "Vägkorsning", "Förbud mot u-sväng"], a: 1, why: "Ett kryss = stannandeförbud. Du får inte stanna fordonet där, mer än för att undvika fara eller i kö." },
  { id: "s10", cat: "skyltar", sign: "pabjudenHoger", q: "Vad betyder det blå runda märket?", opts: ["Rekommenderad väg", "Påbjuden körriktning – du måste köra åt höger", "Förbud att svänga höger", "Parkering till höger"], a: 1, why: "Blå runda märken är påbudsmärken – de talar om vad du måste göra." },
  { id: "s11", cat: "skyltar", sign: "cirkulation", q: "Vad betyder märket?", opts: ["U-sväng tillåten", "Cirkulationsplats", "Vändplan", "Förbud mot vänstersväng"], a: 1, why: "Påbjuden körriktning i cirkulationsplats – du kör moturs runt." },
  { id: "s12", cat: "skyltar", sign: "overgangsstalle", q: "Vad visar märket?", opts: ["Gångfartsområde", "Övergångsställe", "Varning för gående", "Gångbana"], a: 1, why: "Blå skylt med gående på vit triangel = övergångsställe." },
  { id: "s13", cat: "skyltar", sign: "motesplats", q: "Vad betyder skylten med ett M?", opts: ["Motorväg", "Mötesplats – för att underlätta möten på smal väg", "Mataffär", "Max hastighet"], a: 1, why: "M = mötesplats. Där kan du köra in för att släppa förbi mötande. Du får inte parkera där." },
  { id: "s14", cat: "skyltar", sign: "omkorningsforbud", q: "Vad betyder märket?", opts: ["Förbud mot omkörning av motordrivna fordon med fler än två hjul", "Bilköer", "Bilverkstad", "Bogsering förbjuden"], a: 0, why: "Omkörningsförbud: du får inte köra om bilar och andra motorfordon med fler än två hjul." },
  { id: "s15", cat: "skyltar", sign: "gangfart", q: "Du kör in i ett gångfartsområde. Vad gäller?", opts: ["30 km/h", "Du får köra i gångfart och gående har företräde", "Bilar har företräde", "Endast cyklar får köra"], a: 1, why: "I gångfartsområde kör du i gångfart (ca 7 km/h), gående har företräde och du får bara parkera på markerade platser." },
  { id: "s16", cat: "skyltar", sign: "slirig", q: "Vad varnar märket för?", opts: ["Slingrig väg", "Slirig vägbana", "Bilverkstad", "Vägarbete"], a: 1, why: "Varning för slirig vägbana – sänk farten och undvik tvära rörelser." },
  { id: "s17", cat: "skyltar", sign: "farligKurva", q: "Vad varnar märket för?", opts: ["Farlig kurva", "Påbjuden sväng höger", "Avsmalnande väg", "Vägen tar slut"], a: 0, why: "Varning för farlig kurva. Sänk farten innan kurvan börjar." },
  { id: "s18", cat: "skyltar", sign: "korsningUtanForetrade", q: "Vad betyder märket?", opts: ["Korsning där högerregeln gäller", "Kyrka", "Korsning där trafiken från sidovägen har väjningsplikt mot dig", "Förbud mot att svänga"], a: 2, why: "Det tjocka strecket är din väg. Trafiken från den smala vägen ska väja för dig. Var ändå uppmärksam!" },
  { id: "s19", cat: "skyltar", sign: "cyklister", q: "Vad varnar märket för?", opts: ["Cykelbana börjar", "Cyklister och mopedister", "Cykelparkering", "Förbud mot cykel"], a: 1, why: "Gul triangel med cykel = varning för cyklister och mopedister. Det kan till exempel finnas en cykelbana som korsar vägen." },
  { id: "s20", cat: "skyltar", sign: "radjur", q: "Vad varnar märket för?", opts: ["Rådjur", "Älg", "Häst", "Hund"], a: 0, why: "Varning för rådjur. Om du ser ett rådjur kan fler komma efter – sakta in." },
  { id: "s21", cat: "skyltar", sign: "avsmalnande", q: "Vad betyder märket?", opts: ["Motorväg börjar", "Bro", "Två körfält", "Avsmalnande väg"], a: 3, why: "Vägen blir smalare. Sänk farten och var beredd på möten." },
  { id: "s22", cat: "skyltar", sign: "plankorsningBommar", q: "Vad varnar märket för?", opts: ["Plankorsning med bommar", "Staket vid vägen", "Vägbom vid parkering", "Bro över vatten"], a: 0, why: "Märket varnar för en plankorsning med järnväg som har bommar. Stanna när bommarna fälls ner eller signalen blinkar." },
  { id: "s23", cat: "skyltar", sign: "kryssmarke", q: "Var står det här märket (kryssmärke)?", opts: ["Vid en korsning med huvudled", "Vid en sjukhusinfart", "Där en väg är avstängd", "Precis vid en plankorsning där vägen korsar järnväg eller spårväg"], a: 3, why: "Kryssmärket sitter vid själva plankorsningen. Titta och lyssna efter tåg innan du kör över." },
  { id: "s24", cat: "skyltar", sign: "forbudVanster", q: "Vad betyder märket?", opts: ["Förbud mot att svänga vänster", "Påbjuden sväng vänster", "Vänsterkurva", "Förbud mot U-sväng"], a: 0, why: "Röd ring med pil och snett streck = förbud. Här får du inte svänga vänster." },
  { id: "s25", cat: "skyltar", sign: "forbudUsvang", q: "Vad betyder märket?", opts: ["Förbud mot U-sväng", "Cirkulationsplats", "Förbud mot vänstersväng", "Vändplats"], a: 0, why: "Förbud mot U-sväng: du får inte vända här." },
  { id: "s26", cat: "skyltar", sign: "forbudMotorfordon", q: "Vad betyder märket?", opts: ["Motorcykelparkering", "Bilverkstad", "Förbud mot trafik med motordrivna fordon", "Förbud mot omkörning"], a: 2, why: "Här får inga motorfordon köra, till exempel bilar och motorcyklar." },
  { id: "s27", cat: "skyltar", sign: "enkelriktad", q: "Vad betyder märket?", opts: ["Påbjuden körriktning rakt fram", "Motorväg", "Enkelriktad trafik – all trafik kör i pilens riktning", "Rekommenderad väg"], a: 2, why: "Blå rektangel med vit pil = enkelriktad trafik. Här kör alla åt samma håll." },
  { id: "s28", cat: "skyltar", sign: "gagata", q: "Vad gäller på en gata med det här märket?", opts: ["Gångfartsområde för bilar", "Vanlig gata med 30 km/h", "Förbud för gående", "Gågata – fordon får bara köra där i undantagsfall och då i gångfart"], a: 3, why: "På en gågata är det gående som gäller. Om du får köra där, till exempel för att lämna varor, kör du i gångfart och släpper fram gående." },
  { id: "s29", cat: "skyltar", sign: "cykelbana", q: "Vad betyder det blå runda märket med en cykel?", opts: ["Cykeluthyrning", "Varning för cyklister", "Cykelparkering", "Påbjuden cykelbana"], a: 3, why: "Blått runt märke = påbud. Här är det cykelbana – inte väg för bilar." },
  { id: "s30", cat: "skyltar", sign: "gangCykelbana", q: "Vad betyder märket?", opts: ["Övergångsställe", "Varning för barn", "Lekplats", "Gång- och cykelbana"], a: 3, why: "Påbjuden gång- och cykelbana. Den är till för gående och cyklister – inte för bilar." },
  { id: "s31", cat: "skyltar", sign: "atervandsvag", q: "Vad betyder märket?", opts: ["Sjukhus", "Huvudled", "Återvändsväg – vägen tar slut och du kommer inte vidare", "Parkering"], a: 2, why: "Återvändsväg: vägen leder inte vidare. Du måste vända och köra tillbaka samma väg." },
  { id: "s32", cat: "skyltar", sign: "motortrafikled", q: "Vad betyder märket?", opts: ["Motortrafikled", "Bilparkering", "Biltvätt", "Bilfärja"], a: 0, why: "Motortrafikled har liknande regler som motorväg. Du får till exempel inte vända eller backa där." },
  { id: "s33", cat: "skyltar", sign: "annanFara", q: "Vad betyder märket med ett utropstecken?", opts: ["Viktig information om parkering", "Varning för annan fara", "Polis", "Stopp"], a: 1, why: "Varning för annan fara. Ofta finns en tilläggstavla som berättar vad faran är." },
  { id: "s34", cat: "skyltar", sign: "farthinder", q: "Vad varnar märket för?", opts: ["Farthinder, till exempel ett gupp", "Backkrön", "Tunnel", "Ojämn väg i flera km"], a: 0, why: "Varning för farthinder. Sakta in så att du kör över hindret mjukt och säkert." },
  { id: "s35", cat: "skyltar", sign: "motorvagSlut", q: "Vad betyder märket?", opts: ["Motorväg börjar", "Förbud mot motorfordon", "Motorväg upphör", "Motorvägen är avstängd"], a: 2, why: "Ett rött snett streck över motorvägsmärket betyder att motorvägen tar slut. Nu gäller vanliga regler och ofta lägre fart." },
  { id: "s36", cat: "skyltar", sign: "tattbebyggt", q: "Vad visar märket?", opts: ["Industriområde", "Tättbebyggt område börjar", "Campingplats", "Bostadsområde med parkeringsförbud"], a: 1, why: "Tättbebyggt område börjar. Om ingen annan hastighet är skyltad gäller då högst 50 km/h." },
  { id: "s37", cat: "skyltar", sign: "motorvag", q: "Vad betyder märket?", opts: ["Bro", "Tunnel", "Motorväg", "Järnväg"], a: 2, why: "Motorväg börjar. Där får du till exempel inte vända, backa eller stanna på vägen." },
  { id: "s38", cat: "skyltar", sign: "korsning", q: "Vad varnar märket för?", opts: ["Sjukhus", "Vägkorsning", "Kyrka", "Förbud mot att svänga"], a: 1, why: "Varning för vägkorsning. Om inga andra skyltar finns gäller ofta högerregeln där." },
  { id: "s39", cat: "skyltar", sign: "parkering", q: "Vad betyder den blå skylten med ett P?", opts: ["Polis", "Påbjuden väg", "Parkering", "Parkeringsförbud"], a: 2, why: "P = parkering. Tilläggstavlor under kan berätta hur länge du får stå och om det kostar." },

  // ───────── Fart & avstånd ─────────
  { id: "h1", cat: "hastighet", q: "Vilken är den vanliga högsta hastigheten inom tättbebyggt område om inget annat är skyltat?", opts: ["30 km/h", "40 km/h", "50 km/h", "70 km/h"], a: 2, why: "Bashastigheten inom tättbebyggt område är 50 km/h. Ofta är den skyltad lägre, t.ex. 30 eller 40." },
  { id: "h2", cat: "hastighet", q: "Vilken är bashastigheten utanför tättbebyggt område om inget annat är skyltat?", opts: ["70 km/h", "80 km/h", "90 km/h", "100 km/h"], a: 0, why: "Utanför tättbebyggt område är bashastigheten 70 km/h om inget annat är skyltat." },
  { id: "h3", cat: "hastighet", q: "Om du dubblar farten, hur mycket längre blir bromssträckan (ungefär)?", opts: ["Dubbelt så lång", "Tre gånger så lång", "Fyra gånger så lång", "Lika lång"], a: 2, why: "Bromssträckan ökar med kvadraten på farten: 2× fart ≈ 4× bromssträcka." },
  { id: "h4", cat: "hastighet", q: "Vad är stoppsträcka?", opts: ["Bara bromssträckan", "Reaktionssträckan + bromssträckan", "Avståndet till bilen framför", "Sträckan du rullar på frilägg"], a: 1, why: "Stoppsträcka = reaktionssträcka (medan du hinner reagera) + bromssträcka." },
  { id: "h5", cat: "hastighet", q: "Vilket är ett bra säkerhetsavstånd till bilen framför vid torrt väglag?", opts: ["Minst 1 sekund", "Minst 3 sekunder", "Exakt 10 meter", "En billängd"], a: 1, why: "Tresekundersregeln: välj en punkt bilen framför passerar och räkna – du ska passera samma punkt tidigast efter 3 sekunder. Mer vid dåligt väglag." },
  { id: "h6", cat: "hastighet", q: "Ungefär hur lång är reaktionssträckan vid 90 km/h om du har 1 sekunds reaktionstid?", opts: ["Ca 9 meter", "Ca 25 meter", "Ca 50 meter", "Ca 90 meter"], a: 1, why: "90 km/h ≈ 25 m/s. Under 1 sekund hinner bilen 25 meter innan du ens börjat bromsa." },
  { id: "h7", cat: "hastighet", q: "Hur stor chans har en fotgängare att överleva en påkörning i 30 km/h jämfört med 50 km/h?", opts: ["Ingen skillnad", "Mycket större chans i 30 km/h", "Större chans i 50 km/h", "Det beror bara på bilen"], a: 1, why: "I 30 km/h överlever de flesta, i 50 km/h dör betydligt fler. Därför är det ofta 30 nära skolor." },
  { id: "h8", cat: "hastighet", sign: "maxHast30", q: "Du ser det här märket. Vad gäller?", opts: ["Rekommenderad hastighet 30", "Högst 30 km/h", "Minst 30 km/h", "30 meter till korsning"], a: 1, why: "Rött runt märke med siffra = högsta tillåtna hastighet." },
  { id: "h9", cat: "hastighet", q: "Vad är normalt högsta tillåtna hastighet för en personbil som drar en släpvagn?", opts: ["70 km/h", "80 km/h", "100 km/h", "Samma som utan släp"], a: 1, why: "Med släp gäller oftast högst 80 km/h (B-körkort), även om vägen tillåter mer." },
  { id: "h10", cat: "hastighet", q: "När ska du anpassa farten under skyltad hastighet?", opts: ["Aldrig", "När sikt, väglag eller trafik kräver det", "Bara när polisen syns", "Bara på motorväg"], a: 1, why: "Skyltad hastighet är det högsta tillåtna – inte alltid det säkraste. Du ska alltid anpassa farten efter förhållandena." },
  { id: "h11", cat: "hastighet", q: "Vilken är den högsta hastighet som kan vara tillåten på en svensk motorväg?", opts: ["100 km/h", "110 km/h", "120 km/h", "130 km/h"], a: 2, why: "Den högsta hastighetsgränsen i Sverige är 120 km/h. Den finns på vissa motorvägar." },
  { id: "h12", cat: "hastighet", q: "Det är halt och snöigt. Hur ska du tänka kring avståndet till bilen framför?", opts: ["Samma som vanligt räcker", "Håll kortare avstånd så du ser bilens spår", "Håll mycket längre avstånd än vid torrt väglag", "Avståndet spelar ingen roll om du har vinterdäck"], a: 2, why: "På halt väglag blir bromssträckan mycket längre. Därför behöver du mycket mer avstånd än 3 sekunder." },
  { id: "h13", cat: "hastighet", q: "Vad påverkar reaktionssträckan?", opts: ["Bara däckens skick", "Farten och hur snabbt du reagerar – t.ex. om du är trött", "Bara väglaget", "Bilens färg"], a: 1, why: "Reaktionssträckan är sträckan du kör innan du hinner börja bromsa. Hög fart och trötthet gör den längre." },
  { id: "h14", cat: "hastighet", q: "Vad påverkar bromssträckan?", opts: ["Bara hur fort du reagerar", "Bara bilens vikt", "Fart, väglag, däck och bromsar", "Ingenting – den är alltid lika lång"], a: 2, why: "Bromssträckan beror på fart, väglag, däck, bromsar och last. Hög fart och halt väglag gör den mycket längre." },
  { id: "h15", cat: "hastighet", q: "Hur påverkas bromssträckan på is jämfört med torr asfalt?", opts: ["Den blir kortare", "Den blir ungefär lika lång", "Den blir bara någon meter längre", "Den kan bli flera gånger längre"], a: 3, why: "På is har däcken mycket sämre grepp. Bromssträckan kan bli flera gånger längre än på torr väg." },
  { id: "h16", cat: "hastighet", q: "Om du kör dubbelt så fort, hur mycket mer rörelseenergi har bilen?", opts: ["Lika mycket", "Dubbelt så mycket", "Fyra gånger så mycket", "Hälften"], a: 2, why: "Rörelseenergin ökar med farten i kvadrat. Dubbel fart = fyra gånger så mycket energi vid en krock." },
  { id: "h17", cat: "hastighet", q: "Ungefär hur många meter kör du på en sekund i 50 km/h?", opts: ["Ca 5 meter", "Ca 30 meter", "Ca 14 meter", "Ca 50 meter"], a: 2, why: "50 km/h är ungefär 14 meter per sekund. Ett tips: dela km/h med 3,6 för att få meter per sekund." },
  { id: "h18", cat: "hastighet", q: "Hur fort får en moped klass I köra som högst?", opts: ["25 km/h", "30 km/h", "45 km/h", "70 km/h"], a: 2, why: "En moped klass I får köra högst 45 km/h. Tänk på det när du ska köra om eller möter en moped." },
  { id: "h19", cat: "hastighet", q: "Hur fort får en moped klass II köra som högst?", opts: ["20 km/h", "25 km/h", "45 km/h", "50 km/h"], a: 1, why: "En moped klass II får köra högst 25 km/h. Den kör ofta på cykelbanan." },
  { id: "h20", cat: "hastighet", q: "En elsparkcykel räknas som en cykel. Hur fort får motorn hjälpa till som mest?", opts: ["20 km/h", "30 km/h", "45 km/h", "Ingen gräns"], a: 0, why: "En elsparkcykel som räknas som cykel får ha en motor som hjälper till upp till 20 km/h." },
  { id: "h21", cat: "hastighet", q: "Får du köra fortare än hastighetsgränsen när du kör om?", opts: ["Ja, för att det ska gå snabbt", "Ja, med högst 10 km/h", "Ja, på landsväg", "Nej, hastighetsgränsen gäller även vid omkörning"], a: 3, why: "Hastighetsgränsen gäller alltid. Räcker inte farten för att köra om säkert – låt bli." },
  { id: "h22", cat: "hastighet", q: "Vilken regel gäller alltid för din fart?", opts: ["Du ska alltid köra exakt så fort som skylten visar", "Du ska köra lika fort som bilen framför", "Farten spelar ingen roll om du är uppmärksam", "Du ska kunna stanna på den del av vägen som du ser är fri"], a: 3, why: "Du ska alltid kunna stanna på den sträcka du ser framför dig. Kör långsammare när sikten är dålig." },
  { id: "h23", cat: "hastighet", q: "Du kör i mörker med halvljus på en landsväg. Hur ska du välja fart?", opts: ["Så att du kan stanna inom den sträcka som lyses upp", "Samma fart som på dagen", "Så fort som skylten tillåter", "Fortare för att komma hem snabbt"], a: 0, why: "I mörker ser du bara så långt som ljuset når. Kör så att du hinner stanna inom den sträckan." },
  { id: "h24", cat: "hastighet", q: "När är det bäst att bromsa inför en skarp kurva?", opts: ["Mitt i kurvan", "Efter kurvan", "Det behövs inte", "Före kurvan, medan bilen går rakt"], a: 3, why: "Bromsa före kurvan när hjulen är raka. Att bromsa hårt mitt i kurvan kan få bilen att sladda." },
  { id: "h25", cat: "hastighet", q: "Du ska köra om en cyklist på en smal väg. Vad gör du?", opts: ["Väntar tills du kan köra om med god marginal i sidled", "Kör om nära för att inte störa mötande", "Tutar så att cyklisten flyttar sig", "Kör om i samma fart som vanligt"], a: 0, why: "Cyklister kan vingla. Vänta tills det är fritt och ge dem gott om plats när du kör om." },
  { id: "h26", cat: "hastighet", q: "Varför ska du hålla extra långt avstånd bakom en lastbil?", opts: ["Du ser inte vad som händer framför lastbilen", "Lastbilen kan inte bromsa", "Det är en lag för alla lastbilar", "Lastbilar kör alltid fort"], a: 0, why: "Lastbilen skymmer sikten. Med längre avstånd ser du mer och föraren ser dig i sina speglar." },
  { id: "h27", cat: "hastighet", sign: "vagarbete", q: "Du ser det här märket. Hur ska du köra?", opts: ["Som vanligt", "Öka farten för att snabbt komma förbi", "Tuta för att varna arbetarna", "Sänka farten, följa skyltarna och se upp för arbetare"], a: 3, why: "Vid vägarbete kan det finnas människor, maskiner och gropar. Sänk farten och följ skyltad hastighet." },
  { id: "h28", cat: "hastighet", q: "Hur mycket tid sparar du på 10 km om du kör 90 km/h i stället för 80 km/h?", opts: ["Ungefär 50 sekunder", "Ungefär 5 minuter", "Ungefär 10 minuter", "Ungefär en halvtimme"], a: 0, why: "10 km tar 7,5 minuter i 80 och ca 6 minuter och 40 sekunder i 90. Du sparar under en minut – men risken ökar." },
  { id: "h29", cat: "hastighet", q: "Det är tät dimma. Vad gör du?", opts: ["Kör som vanligt med helljus", "Sänker farten och ökar avståndet", "Kör nära bilen framför för att se dess baklampor", "Stannar på vägen"], a: 1, why: "I dimma ser du kort. Sänk farten, öka avståndet och använd halvljus – helljus reflekteras i dimman." },
  { id: "h30", cat: "hastighet", q: "Vad ska du göra i accelerationsfältet när du kör ut på motorvägen?", opts: ["Öka farten så den passar trafiken på motorvägen", "Köra sakta och stanna i slutet", "Köra ut direkt i vänster körfält", "Sätta på varningsblinkers"], a: 0, why: "Accelerationsfältet är till för att få upp farten. Då kan du smidigt glida in i luckan." },
  { id: "h31", cat: "hastighet", q: "Du har kört länge på motorväg och kör nu av till en vanlig väg. Vad kan hända?", opts: ["Du kan tro att du kör långsammare än du gör – kolla hastighetsmätaren", "Du kör ofta långsammare än du tror", "Bilen bromsar sämre", "Ingenting"], a: 0, why: "Efter lång tid i hög fart känns lägre fart väldigt långsam. Titta på hastighetsmätaren." },
  { id: "h32", cat: "hastighet", q: "Bilen är tungt lastad. Hur påverkar det bromssträckan?", opts: ["Den blir kortare", "Ingen skillnad", "Den blir längre", "Den blir kortare i uppförsbacke"], a: 2, why: "En tyngre bil behöver längre sträcka för att stanna. Håll längre avstånd när bilen är full." },
  { id: "h33", cat: "hastighet", sign: "maxHast70", q: "Du ser märket. Det är mörkt och snöigt. Hur fort ska du köra?", opts: ["Precis 70 km/h", "Högst 70 km/h – men långsammare om sikt och väglag kräver det", "Minst 70 km/h", "80 km/h om vägen är tom"], a: 1, why: "70 är det högsta tillåtna. I mörker och snö ska du köra långsammare än så." },
  { id: "h34", cat: "hastighet", sign: "maxHast50", q: "Du ser märket och drar en släpvagn. Vilken är högsta tillåtna hastighet?", opts: ["30 km/h", "50 km/h", "70 km/h", "80 km/h"], a: 1, why: "Med släp får du köra högst 80 km/h, men märket säger 50. Den lägsta gränsen gäller alltid." },

  // ───────── Människan bakom ratten ─────────
  { id: "m1", cat: "manniska", q: "Vid vilken alkoholhalt i blodet räknas det som rattfylleri i Sverige?", opts: ["0,1 promille", "0,2 promille", "0,5 promille", "0,8 promille"], a: 1, why: "Gränsen för rattfylleri är 0,2 promille. Grovt rattfylleri börjar vid 1,0 promille." },
  { id: "m2", cat: "manniska", q: "Vid vilken alkoholhalt räknas det som grovt rattfylleri?", opts: ["0,5 promille", "0,8 promille", "1,0 promille", "2,0 promille"], a: 2, why: "Grovt rattfylleri gäller från 1,0 promille, eller om du kör påtagligt påverkad." },
  { id: "m3", cat: "manniska", q: "Får du använda en handhållen mobil när du kör?", opts: ["Ja, om du kör långsamt", "Nej, du får inte hålla i mobilen och använda den under körning", "Ja, för att skriva sms", "Ja, i stillastående kö"], a: 1, why: "Det är förbjudet att hålla i mobilen och använda den under körning. Även handsfree kan distrahera – använd bara om det är säkert." },
  { id: "m4", cat: "manniska", q: "Vad är bästa sättet att bli av med trötthet bakom ratten?", opts: ["Öppna fönstret", "Höja musiken", "Stanna och vila/sova en stund", "Dricka energidryck och fortsätta"], a: 2, why: "Det enda som verkligen hjälper är att stanna och vila. Fönster och musik hjälper bara några minuter." },
  { id: "m5", cat: "manniska", q: "Hur lång tid tar det ungefär för kroppen att förbränna alkoholen från en stor stark öl (50 cl)?", opts: ["15 minuter", "Ca 1 timme", "Ca 2–3 timmar", "Den försvinner direkt"], a: 2, why: "Kroppen förbränner ungefär 0,1 g alkohol per kg kroppsvikt och timme. En stor stark öl kan ta flera timmar – kaffe eller kall dusch hjälper inte." },
  { id: "m6", cat: "manniska", q: "Vad kan hända med synen när du är trött eller påverkad?", opts: ["Den blir bättre", "Synfältet krymper (tunnelseende)", "Inget", "Du ser bättre i mörker"], a: 1, why: "Trötthet, alkohol och stress kan ge tunnelseende – du ser mindre av det som händer runt omkring." },
  { id: "m7", cat: "manniska", q: "Vilket påstående om läkemedel stämmer?", opts: ["Receptbelagda mediciner påverkar aldrig körningen", "Vissa läkemedel är märkta med en röd varningstriangel och kan påverka körförmågan", "Det är bara alkohol som är farligt", "Huvudvärkstabletter är förbjudna"], a: 1, why: "Läkemedel med röd varningstriangel kan påverka din förmåga att köra. Läs bipacksedeln och fråga läkare/apotek." },
  { id: "m8", cat: "manniska", q: "Hur länge är prövotiden efter att du fått B-körkort?", opts: ["6 månader", "1 år", "2 år", "5 år"], a: 2, why: "Prövotiden är 2 år. Om körkortet återkallas under prövotiden måste du göra om både kunskapsprov och körprov." },
  { id: "m9", cat: "manniska", q: "Varför är unga, nya förare överrepresenterade i olyckor?", opts: ["De har sämre bilar", "Lite erfarenhet och ibland överskattning av den egna förmågan", "De kör alltid för långsamt", "Det stämmer inte"], a: 1, why: "Erfarenhet tar tid. Nya förare kan ha svårt att upptäcka risker och kan överskatta sin förmåga." },
  { id: "m10", cat: "manniska", q: "Vad innebär grupptryck i bilen?", opts: ["Att passagerare påverkar dig att köra fortare eller ta risker", "Att bilen har för högt lufttryck", "Att du kör i kolonn", "Att alla har bälte"], a: 0, why: "Kompisar i bilen kan påverka hur du kör. Du som förare bestämmer – och har ansvaret." },
  { id: "m11", cat: "manniska", q: "Vad gäller för narkotika och bilkörning?", opts: ["Lite är okej", "Det är bara förbjudet på natten", "Bara alkohol är förbjudet", "Det är förbjudet att köra med narkotika i blodet (om det inte är medicin du fått på recept)"], a: 3, why: "Sverige har nolltolerans. Har du narkotika i blodet är det drograttfylleri – även om du känner dig pigg." },
  { id: "m12", cat: "manniska", q: "Vad hjälper för att bli nykter snabbare?", opts: ["Starkt kaffe", "Kall dusch", "Att äta mycket", "Inget – bara tid hjälper"], a: 3, why: "Kroppen förbränner alkohol i sin egen takt. Kaffe, dusch eller mat gör dig inte nykter snabbare." },
  { id: "m13", cat: "manniska", q: "Du drack mycket alkohol sent igår kväll. Kan du köra bil på morgonen?", opts: ["Ja, du har sovit", "Ja, om du dricker kaffe", "Det är inte säkert – du kan fortfarande ha alkohol i blodet", "Ja, om du kör sakta"], a: 2, why: "Alkohol kan finnas kvar i blodet länge, även nästa dag. Vänta tills du är helt nykter." },
  { id: "m14", cat: "manniska", q: "Vilket är ett tecken på att du är för trött för att köra?", opts: ["Du gäspar mycket och minns inte de senaste kilometrarna", "Du sjunger med i en låt", "Du är hungrig", "Du vill komma fram"], a: 0, why: "Gäspningar, tunga ögonlock och att du glömmer bort vägen är varningssignaler. Stanna och vila!" },
  { id: "m15", cat: "manniska", q: "Vad är mikrosömn?", opts: ["En kort powernap på en rastplats", "En typ av sömntablett", "Att du somnar några sekunder utan att märka det", "Att sova i bilen"], a: 2, why: "Vid mikrosömn somnar du i några sekunder. I 90 km/h hinner bilen köra ca 25 meter varje sekund – utan förare." },
  { id: "m16", cat: "manniska", q: "Du tittar ner på mobilen i 2 sekunder när du kör i 70 km/h. Hur långt kör du utan att se vägen?", opts: ["Ca 4 meter", "Ca 40 meter", "Ca 15 meter", "Ca 140 meter"], a: 1, why: "70 km/h är ca 19 meter per sekund. På 2 sekunder kör du nästan 40 meter i blindo." },
  { id: "m17", cat: "manniska", q: "När är det bäst att ställa in GPS:en?", opts: ["Innan du börjar köra", "Medan du kör på motorvägen", "I rödljus", "När du kör om"], a: 0, why: "Ställ in navigationen innan du kör. Då kan du ha full koll på trafiken under resan." },
  { id: "m18", cat: "manniska", q: "Vad betyder det att 'titta men inte se'?", opts: ["Att du har dålig syn", "Att du blundar", "Att du har solglasögon", "Att ögonen riktas mot något men hjärnan inte uppfattar det, t.ex. när du är distraherad"], a: 3, why: "Om tankarna är någon annanstans kan du missa en cyklist fast du tittar åt hennes håll. Fokusera på körningen." },
  { id: "m19", cat: "manniska", q: "Du är stressad och sen till ett möte. Vad är klokast?", opts: ["Acceptera att du blir sen och kör lugnt", "Kör fortare för att hinna", "Kör om så mycket som möjligt", "Ring och prata i mobilen medan du kör"], a: 0, why: "Stress gör att vi tar fler risker. Planera tid i förväg – och om du blir sen, kör ändå lugnt." },
  { id: "m20", cat: "manniska", q: "En annan förare blir arg och tutar på dig. Vad gör du?", opts: ["Bromsar för att straffa hen", "Tutar tillbaka", "Kör efter hen", "Håller dig lugn och låter hen vara"], a: 3, why: "Gå inte in i en konflikt i trafiken. Behåll lugnet – det är säkrast för alla." },
  { id: "m21", cat: "manniska", q: "Ditt körkort har ett villkor om glasögon eller linser. Vad gäller?", opts: ["Du måste alltid använda dem när du kör", "Du behöver bara ha dem i mörker", "Du behöver bara ha dem med i bilen", "Det är bara en rekommendation"], a: 0, why: "Står det villkor om glasögon eller linser i körkortet måste du alltid använda dem när du kör." },
  { id: "m22", cat: "manniska", q: "Vad gör en läkare om en patient på grund av sjukdom inte längre kan köra säkert?", opts: ["Läkaren ska anmäla det till Transportstyrelsen", "Inget, det är hemligt", "Läkaren tar körkortet själv", "Läkaren ringer polisen"], a: 0, why: "Läkare måste anmäla till Transportstyrelsen om någon av medicinska skäl inte är lämplig att köra." },
  { id: "m23", cat: "manniska", q: "Vad är spärrtid?", opts: ["Tiden du måste vänta vid ett rödljus", "Tiden mellan kunskapsprov och körprov", "En tid efter att körkortet återkallats då du inte kan få ett nytt körkort", "Parkeringstid"], a: 2, why: "När körkortet återkallas bestäms en spärrtid. Under den tiden kan du inte få nytt körkort." },
  { id: "m24", cat: "manniska", q: "Vad gör ett alkolås?", opts: ["Låser bilen när du dricker", "Mäter hur trött du är", "Hindrar bilen från att starta om föraren har druckit alkohol", "Låser dörrarna under körning"], a: 2, why: "Föraren blåser i alkolåset innan start. Finns det alkohol i utandningsluften startar inte bilen." },
  { id: "m25", cat: "manniska", q: "Vad påverkar hur hög din promillehalt blir?", opts: ["Bara vad du dricker", "Bara hur gammal du är", "Ingenting – den blir alltid lika", "Mängden alkohol, din vikt, om du ätit och hur snabbt du dricker"], a: 3, why: "Promillehalten beror på mycket. Därför går det inte att räkna ut säkert om du är nykter – kör inte om du druckit." },
  { id: "m26", cat: "manniska", q: "Du tar en medicin som läkaren skrivit ut och som är narkotikaklassad. Får du köra bil?", opts: ["Aldrig", "Ja, hur mycket du än tar", "Bara på dagtid", "Ja, om du tar den enligt ordination och inte är så påverkad att du kör osäkert"], a: 3, why: "Medicin enligt recept är tillåten, men du får aldrig köra om du är påverkad. Fråga läkaren och läs bipacksedeln." },
  { id: "m27", cat: "manniska", q: "Du är passagerare och föraren verkar trött. Vad gör du?", opts: ["Somnar själv", "Sätter på hög musik", "Inget, det är inte ditt ansvar", "Pratar med föraren och föreslår en paus"], a: 3, why: "Som passagerare kan du hjälpa till. Säg till och föreslå att ni stannar och vilar." },
  { id: "m28", cat: "manniska", q: "En förare får en ny bil med ABS och antisladd och börjar köra fortare på halt väglag. Vad kallas det?", opts: ["Eco-driving", "Defensiv körning", "Riskkompensation", "Framförhållning"], a: 2, why: "Riskkompensation är när man tar större risker för att man känner sig säker. Tekniken kan inte ändra fysikens lagar." },
  { id: "m29", cat: "manniska", q: "Hur påverkas synen i mörker när man blir äldre?", opts: ["Man behöver mer ljus och blir lättare bländad", "Man ser bättre", "Ingen skillnad", "Man ser bara i svartvitt"], a: 0, why: "Med åldern behöver ögonen mer ljus och tar längre tid att återhämta sig efter bländning." },
  { id: "m30", cat: "manniska", q: "Du har varit inblandad i en trafikolycka. Vad måste du göra?", opts: ["Köra därifrån så snabbt som möjligt", "Stanna, hjälpa till och lämna namn och adress", "Bara stanna om det är din bil som är skadad", "Vänta hemma på att polisen ringer"], a: 1, why: "Alla som är inblandade i en olycka måste stanna och hjälpa till. Att köra därifrån kallas smitning och är ett brott." },
  { id: "m31", cat: "manniska", q: "Vad händer normalt med körkortet om du döms för rattfylleri?", opts: ["Det återkallas", "Inget", "Du får en varning", "Du måste bara betala parkeringsavgift"], a: 0, why: "Rattfylleri leder normalt till att körkortet återkallas – och till böter eller fängelse." },
  { id: "m32", cat: "manniska", q: "Du ska köra en lång sträcka. Vad är klokt?", opts: ["Köra hela vägen utan stopp", "Köra på natten när det är lugnt", "Ta pauser regelbundet, till exempel ungefär varannan timme", "Dricka energidryck i stället för att vila"], a: 2, why: "Regelbundna pauser gör att du håller dig pigg. Rör på dig och vila om du blir trött." },

  // ───────── Risker & väglag ─────────
  { id: "k1", cat: "risk", q: "Bilen börjar vattenplana (aquaplaning). Vad gör du?", opts: ["Bromsar hårt", "Släpper gasen och håller ratten stilla tills däcken får grepp", "Gasar för att komma ur", "Svänger kraftigt"], a: 1, why: "Släpp gasen, håll ratten rakt och vänta tills däcken får kontakt med vägen igen. Undvik tvära rörelser." },
  { id: "k2", cat: "risk", q: "När är risken för viltolyckor störst?", opts: ["Mitt på dagen", "I gryning och skymning", "Bara på vintern", "Bara i städer"], a: 1, why: "Djur rör sig mest i gryning och skymning. Håll utkik längs vägkanterna och sänk farten." },
  { id: "k3", cat: "risk", q: "Du har krockat med ett rådjur. Vad ska du göra?", opts: ["Köra vidare", "Markera platsen, ringa 112 och rapportera olyckan", "Ta med djuret hem", "Vänta tills det blir ljust"], a: 1, why: "Krock med t.ex. älg, rådjur, hjort eller vildsvin måste anmälas till polisen (112). Sätt ut varningstriangel och markera platsen." },
  { id: "k4", cat: "risk", q: "När ska du byta från helljus till halvljus?", opts: ["Aldrig", "När du möter andra fordon eller kör nära någon framför", "Bara i stan", "När det regnar"], a: 1, why: "Helljuset bländar andra. Byt till halvljus vid möte och när du kör bakom någon." },
  { id: "k5", cat: "risk", q: "Var är det störst risk för halka när temperaturen ligger kring 0 grader?", opts: ["På broar och i skuggiga partier", "I uppförsbackar i solen", "På raksträckor i stan", "Överallt lika"], a: 0, why: "Broar kyls från både ovan och under och fryser först. Skuggor håller kvar is längre." },
  { id: "k6", cat: "risk", q: "Hur långt bakom bilen bör varningstriangeln placeras på en vanlig landsväg?", opts: ["2–5 meter", "10–20 meter", "50–100 meter", "Minst 1 km"], a: 2, why: "Placera triangeln ca 50–100 meter bakom bilen så att andra hinner bromsa. På motorväg längre bort." },
  { id: "k7", cat: "risk", q: "Vilka trafikanter kallas oskyddade?", opts: ["Bussar och lastbilar", "Gående, cyklister, mopedister och motorcyklister", "Bilar utan försäkring", "Taxibilar"], a: 1, why: "Oskyddade trafikanter har ingen kaross runt sig och skadas svårt vid olyckor. Var extra uppmärksam på dem." },
  { id: "k8", cat: "risk", q: "Bilen sladdar. Vart ska du titta?", opts: ["På hindret du är rädd att träffa", "Dit du vill att bilen ska åka", "Ner på pedalerna", "I backspegeln"], a: 1, why: "Du styr dit du tittar. Titta och styr mot den väg du vill köra." },
  { id: "k9", cat: "risk", q: "Varför ska gående använda reflex i mörker?", opts: ["Det är snyggt", "En förare med halvljus ser en gående utan reflex först på ca 25–50 meter, med reflex på mycket längre håll", "Det krävs enligt lag för alla", "För att lysa upp vägen"], a: 1, why: "Med reflex syns gående på 125 meter eller mer, utan reflex mycket senare. Det är skillnaden mellan att hinna stanna eller inte." },
  { id: "k10", cat: "risk", q: "Vad är en döda vinkel?", opts: ["En vinkel där vägen är stängd", "Ett område runt bilen som du inte ser i backspeglarna", "En skarp kurva", "Ett parkeringsförbud"], a: 1, why: "Döda vinkeln syns inte i speglarna. Vrid på huvudet och titta innan du byter körfält." },
  { id: "k11", cat: "risk", q: "Du ska köra över en järnvägskorsning med bommar som börjar fällas ned. Vad gör du?", opts: ["Kör snabbt under bommarna", "Stannar före och väntar", "Tutar", "Kör i sicksack mellan bommarna"], a: 1, why: "När bommarna fälls ned eller ljussignalen blinkar måste du stanna. Tåg har mycket lång bromssträcka." },
  { id: "k12", cat: "risk", q: "Vad står L-ABC för när du hjälper till vid en olycka?", opts: ["Ljus, Avstånd, Bälte, Cykel", "Larma, Avvakta, Bromsa, Cykla", "Livsfarligt läge, Andning, Blödning, Chock", "Lugn, Andas, Bära, Ringa"], a: 2, why: "L-ABC: flytta ut ur livsfarligt läge, kontrollera andning, stoppa blödning och förebygg chock." },
  { id: "k13", cat: "risk", q: "Vilket nummer ringer du vid en olycka där någon är skadad?", opts: ["114 14", "112", "1177", "911"], a: 1, why: "112 är nödnumret i Sverige och hela EU. 114 14 är polisens nummer när det inte är akut." },
  { id: "k14", cat: "risk", q: "Bilen har stannat på grund av motorstopp längs en landsväg. Vad gör du först?", opts: ["Går därifrån och lämnar bilen", "Sätter på varningsblinkers, tar på reflexväst och sätter ut varningstriangeln", "Lägger dig under bilen och lagar", "Väntar i bilen utan att göra något"], a: 1, why: "Gör dig och bilen synlig. Varningsblinkers, reflexväst och varningstriangel varnar andra förare." },
  { id: "k15", cat: "risk", q: "Ett rådjur springer över vägen framför dig. Vad ska du tänka på?", opts: ["Faran är över", "Tuta och öka farten", "Fler djur kan komma efter – sakta in", "Blinka med helljuset"], a: 2, why: "Djur går ofta i grupp. Där ett djur har gått över kan fler komma efter." },
  { id: "k16", cat: "risk", q: "Bilen har ABS. Hur bromsar du i en nödsituation?", opts: ["Pumpar med bromsen", "Bromsar försiktigt", "Drar i handbromsen", "Trycker bromsen hårt och håller kvar – du kan fortfarande styra"], a: 3, why: "Med ABS trycker du hårt och håller kvar. Hjulen låser sig inte, så du kan styra runt hindret." },
  { id: "k17", cat: "risk", q: "Vad gör antisladdsystemet (ESC)?", opts: ["Gör att bilen aldrig kan sladda", "Gör bromssträckan kortare på is", "Hjälper till att hålla bilen på rätt kurs genom att bromsa enskilda hjul", "Tänder lamporna automatiskt"], a: 2, why: "ESC hjälper dig att undvika sladd, men det kan inte ändra fysikens lagar. Kör ändå efter väglaget." },
  { id: "k18", cat: "risk", q: "Vad är svartis?", opts: ["Smutsig snö", "Is som bara finns på natten", "Tunn, blank is som är svår att se på vägen", "Is på vindrutan"], a: 2, why: "Svartis är så tunn och blank att vägen bara ser våt ut. Var försiktig när det är runt noll grader." },
  { id: "k19", cat: "risk", q: "Hur kan du testa väggreppet på vintern?", opts: ["Gasa hårt i en kurva", "Tvärbromsa i en korsning", "Titta på andra bilar", "Provbromsa försiktigt på en rak väg när ingen är bakom dig"], a: 3, why: "En försiktig provbromsning, när det är säkert, visar hur halt det är. Anpassa sedan farten." },
  { id: "k20", cat: "risk", q: "Bilen fortsätter rakt fram fast du svänger i en kurva (framhjulen glider). Vad gör du?", opts: ["Gasar mer", "Vrider ratten ännu mer", "Drar i handbromsen", "Släpper gasen och minskar rattutslaget lite tills hjulen får grepp"], a: 3, why: "Det kallas understyrning. Släpp gasen och vrid tillbaka ratten lite, så får framhjulen grepp igen." },
  { id: "k21", cat: "risk", q: "En lastbil ska svänga höger i en korsning. Var är det farligt att vara?", opts: ["Bredvid lastbilens högra sida", "Långt bakom lastbilen", "Mitt emot på andra sidan korsningen", "Det är aldrig farligt"], a: 0, why: "Lastbilsföraren har en stor död vinkel på höger sida. Cyklister och gående där syns inte." },
  { id: "k22", cat: "risk", q: "Var ska en elsparkcykel köras?", opts: ["På trottoaren", "På motorvägen", "Var som helst", "På cykelbanan, eller på körbanan om det inte finns cykelbana"], a: 3, why: "Elsparkcyklar räknas som cyklar. De ska köras på cykelbanan – inte på trottoaren." },
  { id: "k23", cat: "risk", q: "Du kör förbi en buss som står vid en hållplats. Vad är den största risken?", opts: ["Någon kan springa ut framför bussen", "Bussen kör baklänges", "Bussen tappar last", "Det finns ingen risk"], a: 0, why: "Människor som gått av bussen kan plötsligt gå ut i vägen. Sänk farten och var beredd att stanna." },
  { id: "k24", cat: "risk", q: "Det börjar brinna i en tunnel och du kan inte köra ut. Vad gör du?", opts: ["Stannar, stänger av motorn, lämnar nyckeln i bilen och går till närmaste nödutgång", "Stannar kvar i bilen", "Backar ut ur tunneln", "Tar med bilnyckeln och går mot branden"], a: 0, why: "Rök är farlig. Gå till en nödutgång. Lämna nyckeln i bilen så att räddningstjänsten kan flytta den." },
  { id: "k25", cat: "risk", q: "Får du stanna eller parkera i en tunnel?", opts: ["Ja, om du har varningsblinkers på", "Ja, i högst 5 minuter", "Ja, på natten", "Nej, det är förbjudet (utom vid fara eller kö)"], a: 3, why: "I en tunnel är det trångt och svårt att se. Du får inte stanna eller parkera där." },
  { id: "k26", cat: "risk", q: "Du kommer till en plankorsning utan bommar och utan ljussignal. Vad gör du?", opts: ["Saktar in, tittar och lyssnar efter tåg åt båda hållen", "Kör över snabbt", "Tutar och kör", "Stannar mitt på spåret och tittar"], a: 0, why: "Tåg kan inte stanna snabbt. Titta och lyssna noga innan du kör över – och stanna aldrig på spåret." },
  { id: "k27", cat: "risk", q: "Du blir bländad av en mötande bil i mörker. Vad gör du?", opts: ["Blinkar med helljus tillbaka", "Tittar mot högra vägkanten och sänker farten", "Blundar en stund", "Ökar farten för att komma förbi"], a: 1, why: "Titta mot högra vägkanten så du ser var vägen går. Sänk farten tills du ser bra igen." },
  { id: "k28", cat: "risk", q: "Bilen har gått sönder på motorvägen. Var ska du och passagerarna vänta på hjälp?", opts: ["Bakom räcket eller långt från vägen", "I bilen", "På vägrenen bredvid bilen", "Mitt på vägen så att andra ser er"], a: 0, why: "På motorväg går trafiken fort. Gå ut på den sida som är bort från trafiken och vänta bakom räcket." },
  { id: "k29", cat: "risk", q: "Din bil ska bogseras. Vad behöver du tänka på?", opts: ["Ratten och bromsen kan bli mycket tyngre om motorn är avstängd", "Du kan sova under tiden", "Du behöver inte styra", "Du ska stänga av tändningen så att ratten låses"], a: 0, why: "Utan motor fungerar inte servot. Ratt och broms blir tunga. Ha tändningen på så att ratten inte låser sig." },
  { id: "k30", cat: "risk", q: "En skadad person är medvetslös men andas. Hur lägger du hen?", opts: ["På rygg", "Sittande", "I stabilt sidoläge", "På magen med armarna under sig"], a: 2, why: "Stabilt sidoläge håller luftvägarna fria. Kolla andningen hela tiden tills hjälp kommer." },
  { id: "k31", cat: "risk", q: "När ska du flytta en skadad person från en olycksbil?", opts: ["Alltid direkt", "Aldrig", "När hen ber om det", "Bara om hen är i livsfara där, t.ex. om bilen brinner"], a: 3, why: "Flytta bara en skadad person om det är livsfarligt att stanna kvar. Annars kan skadorna bli värre." },
  { id: "k32", cat: "risk", q: "Du kör nära en skola. Varför ska du vara extra försiktig?", opts: ["Det finns alltid poliser där", "Vägarna är smalare", "Det är inte nödvändigt", "Barn kan göra oväntade saker och har svårt att bedöma bilars fart"], a: 3, why: "Barn är små, syns dåligt och kan plötsligt springa ut. Sänk farten och var beredd att stanna." },
  { id: "k33", cat: "risk", q: "Du kör förbi en rad med parkerade bilar. Vad ska du se upp för?", opts: ["Ingenting", "Att bilarna börjar rulla av sig själva", "Att en bildörr kan öppnas eller att någon går ut mellan bilarna", "Att parkeringsautomaten går sönder"], a: 2, why: "Håll avstånd till parkerade bilar. En dörr kan öppnas och barn kan komma fram mellan bilarna." },

  // ───────── Miljö & eco-driving ─────────
  { id: "e1", cat: "miljo", q: "Vad är eco-driving?", opts: ["Att köra så fort som möjligt", "Ett sparsamt och säkert körsätt som minskar bränsleförbrukningen", "Att bara köra elbil", "Att köra i lågt varvtal på ettan"], a: 1, why: "Eco-driving = mjuk och framförhållande körning, rätt växel och rätt däcktryck. Sparar pengar och miljö." },
  { id: "e2", cat: "miljo", q: "Vilken växel ska du helst köra på för att spara bränsle (manuell bil)?", opts: ["Lägsta möjliga", "Högsta möjliga växel som fungerar för farten", "Alltid trean", "Det spelar ingen roll"], a: 1, why: "Växla upp tidigt och kör på högsta möjliga växel – motorn går då på lågt varvtal och drar mindre." },
  { id: "e3", cat: "miljo", q: "Hur påverkar för lågt däcktryck bränsleförbrukningen?", opts: ["Förbrukningen ökar", "Förbrukningen minskar", "Ingen påverkan", "Bilen går fortare"], a: 0, why: "Lågt däcktryck ökar rullmotståndet – bilen drar mer och däcken slits snabbare. Kolla trycket ofta." },
  { id: "e4", cat: "miljo", q: "Vad är ett bra sätt att minska förbrukningen när du närmar dig ett rödljus?", opts: ["Gasa och tvärbromsa", "Släppa gasen tidigt och låta bilen motorbromsa", "Lägga i friläge och rulla", "Stänga av motorn i farten"], a: 1, why: "Motorbroms med växeln i: moderna bilar stänger då av bränsletillförseln. Framförhållning sparar mest." },
  { id: "e5", cat: "miljo", q: "Vad händer med förbrukningen om du har en takbox som inte används?", opts: ["Ingenting", "Den ökar på grund av luftmotstånd", "Den minskar", "Bilen blir stabilare"], a: 1, why: "Takboxar och takräcken ökar luftmotståndet. Ta bort dem när de inte behövs." },
  { id: "e6", cat: "miljo", q: "Vad är tomgångskörning och varför ska den undvikas?", opts: ["Att köra utan passagerare", "Att låta motorn gå när bilen står still – det slösar bränsle och ger avgaser", "Att köra på tom tank", "Att köra i 30 km/h"], a: 1, why: "Tomgång ger utsläpp utan nytta. Många kommuner har regler om max 1 minut tomgång." },
  { id: "e7", cat: "miljo", q: "Varför är kallstarter dåliga för miljön?", opts: ["Motorn och katalysatorn ger mer utsläpp innan de blivit varma", "De ger mer kraft", "De sliter på däcken", "De är inte dåliga"], a: 0, why: "En kall motor ger mycket mer avgaser. Använd motorvärmare på vintern." },
  { id: "e8", cat: "miljo", q: "Hur påverkar hög fart bränsleförbrukningen?", opts: ["Förbrukningen ökar kraftigt eftersom luftmotståndet ökar", "Den minskar", "Ingen skillnad", "Bara elbilar påverkas"], a: 0, why: "Luftmotståndet ökar mycket med farten. 110 i stället för 90 kan öka förbrukningen märkbart." },
  { id: "e9", cat: "miljo", q: "Vad innebär framförhållning?", opts: ["Att köra nära bilen framför", "Att läsa av trafiken långt fram och planera din körning", "Att hålla ratten långt fram", "Att alltid köra i vänster körfält"], a: 1, why: "Framförhållning gör körningen säkrare och jämnare – du slipper onödiga inbromsningar." },
  { id: "e10", cat: "miljo", q: "Hur hänger bränsleförbrukning och koldioxid (CO₂) ihop?", opts: ["Ju mer bensin eller diesel bilen drar, desto mer CO₂ släpper den ut", "De har inget med varandra att göra", "Mer bränsle ger mindre CO₂", "Bara elbilar släpper ut CO₂"], a: 0, why: "Koldioxiden kommer från bränslet som förbränns. Kör du snålt släpper du ut mindre." },
  { id: "e11", cat: "miljo", q: "Vad är en fördel med en elbil i staden?", opts: ["Den behöver aldrig laddas", "Den har inga däck som slits", "Den släpper inte ut några avgaser från bilen", "Den får köra på cykelbanan"], a: 2, why: "En elbil har inget avgasrör. Det ger renare luft där folk bor." },
  { id: "e12", cat: "miljo", q: "Hur påverkar kyla en elbil?", opts: ["Räckvidden blir längre", "Räckvidden blir kortare", "Ingen påverkan", "Bilen går inte att köra"], a: 1, why: "Batteriet fungerar sämre när det är kallt och värmen i bilen drar el. Räckvidden blir kortare på vintern." },
  { id: "e13", cat: "miljo", q: "Du snabbladdar en elbil. Varför går det långsammare mot slutet?", opts: ["Batteriet laddas långsammare när det är nästan fullt, för att skydda det", "Laddaren blir trött", "Det beror på vädret", "Det gör det inte"], a: 0, why: "Laddningen går snabbast när batteriet är ganska tomt. Mot fullt går det långsamt – det sparar batteriet." },
  { id: "e14", cat: "miljo", q: "Vad är regenerativ bromsning i en elbil eller hybrid?", opts: ["Att bromsarna byts automatiskt", "Att bilen bromsar själv vid rödljus", "En typ av handbroms", "Att bilen tar tillvara energi när den saktar in och laddar batteriet"], a: 3, why: "När du släpper gasen eller bromsar kan elmotorn göra om rörelsen till el. Mjuk körning ger mer energi tillbaka." },
  { id: "e15", cat: "miljo", q: "Hur ska du ladda en elbil hemma på ett säkert sätt?", opts: ["Med en laddbox eller ett uttag som är gjort för laddning", "Med en lång skarvsladd från ett vanligt uttag", "Med flera skarvsladdar i rad", "Det spelar ingen roll"], a: 0, why: "Laddning drar mycket ström länge. Skarvsladdar kan bli varma och börja brinna. Använd utrustning för billaddning." },
  { id: "e16", cat: "miljo", q: "Varför är det bra att använda motorvärmare på vintern?", opts: ["Det gör bilen snabbare", "Det laddar batteriet i en elbil", "Det behövs bara på sommaren", "Bilen startar lättare och släpper ut mindre avgaser vid start"], a: 3, why: "En varm motor slits mindre, drar mindre bränsle och ger mindre utsläpp vid kallstart." },
  { id: "e17", cat: "miljo", q: "Vad består bränslet E85 mest av?", opts: ["Etanol", "Diesel", "El", "Vätgas"], a: 0, why: "E85 består till största delen av etanol och resten bensin. Bilen måste vara byggd för E85." },
  { id: "e18", cat: "miljo", q: "Varför har vissa gator förbud mot dubbdäck?", opts: ["Dubbarna sliter på vägen och ger partiklar som är dåliga att andas in", "Dubbdäck är för tysta", "De gör bilen för snabb", "För att spara bensin"], a: 0, why: "Dubbarna river upp asfalt till små partiklar i luften. Därför kan kommuner förbjuda dubbdäck på vissa gator." },
  { id: "e19", cat: "miljo", q: "Vad är en miljözon?", opts: ["En park där man inte får gå", "En plats för återvinning", "Ett område där bara fordon som klarar vissa miljökrav får köra", "En laddstation"], a: 2, why: "Kommuner kan inrätta miljözoner för att få renare luft. Kolla skyltarna innan du kör in." },
  { id: "e20", cat: "miljo", q: "Hur påverkar luftkonditionering (AC) förbrukningen?", opts: ["Förbrukningen minskar", "Ingen påverkan", "Förbrukningen ökar", "Den laddar batteriet"], a: 2, why: "AC drar energi. Använd den smart, men om rutorna immar igen är det viktigare att se bra." },
  { id: "e21", cat: "miljo", q: "Du har tunga saker i bagaget som du inte behöver. Vad händer?", opts: ["Bilen drar mindre bränsle", "Ingenting", "Bilen blir snabbare", "Bilen drar mer bränsle"], a: 3, why: "Mer vikt kräver mer energi, särskilt när du accelererar. Töm bagaget på onödiga saker." },
  { id: "e22", cat: "miljo", q: "Hur ska du accelerera för att köra sparsamt med en manuell bil?", opts: ["Gasa hårt och varva högt på varje växel", "Krypa fram på ettan länge", "Det spelar ingen roll", "Accelerera mjukt men bestämt och växla upp tidigt"], a: 3, why: "Växla upp tidigt och undvik höga varv. Då arbetar motorn effektivt." },
  { id: "e23", cat: "miljo", q: "Hur kan farthållaren hjälpa dig att köra snålt?", opts: ["Den gör att bilen bromsar mer", "Den ökar farten i backar", "Den stänger av motorn", "Den håller en jämn fart på plan väg"], a: 3, why: "Jämn fart drar mindre bränsle än att gasa och bromsa hela tiden." },
  { id: "e24", cat: "miljo", q: "Varför är korta bilresor dåliga för miljön?", opts: ["De tar för lång tid", "Bilen blir för varm", "Motorn hinner inte bli varm och släpper ut mer per kilometer", "Det är de inte"], a: 2, why: "En kall motor drar mer och släpper ut mer. Gå, cykla eller åk kollektivt på korta sträckor om du kan." },
  { id: "e25", cat: "miljo", q: "Vilket är ett bra sätt att minska utsläppen från resor till jobbet?", opts: ["Samåka eller åka kollektivt", "Åka själv i en stor bil", "Köra fortare", "Köra omvägar"], a: 0, why: "Ju fler som delar på en bil eller buss, desto mindre utsläpp per person." },
  { id: "e26", cat: "miljo", q: "När ska du kontrollera däcktrycket?", opts: ["Bara vid besiktning", "Regelbundet, gärna en gång i månaden, när däcken är kalla", "Bara när ett däck är punkterat", "Aldrig, bilen sköter det"], a: 1, why: "Rätt däcktryck sparar bränsle och ger bättre grepp. Kolla när däcken är kalla – då blir mätningen rätt." },
  { id: "e27", cat: "miljo", q: "Var är det bäst att tvätta bilen?", opts: ["I en biltvätt som renar vattnet", "På gatan utanför huset", "Vid en sjö", "På en parkering"], a: 0, why: "Smuts, olja och kemikalier från bilen kan rinna ut i naturen. En biltvätt renar vattnet." },
  { id: "e28", cat: "miljo", q: "Vad gör du med gammal motorolja eller ett gammalt bilbatteri?", opts: ["Slänger i soporna", "Häller ut i naturen", "Lämnar till återvinningscentral eller verkstad", "Gräver ner det"], a: 2, why: "Olja och batterier är farligt avfall. Lämna dem till en återvinningscentral eller verkstad." },
  { id: "e29", cat: "miljo", q: "Hur påverkar hög fart bullret från trafiken?", opts: ["Bullret minskar", "Bullret ökar", "Ingen skillnad", "Bara lastbilar bullrar"], a: 1, why: "Ju fortare du kör, desto mer buller från däck och vind. Lägre fart ger en tystare miljö." },
  { id: "e30", cat: "miljo", q: "Vad gör katalysatorn i en bensinbil?", opts: ["Gör bilen snabbare", "Minskar mängden skadliga ämnen i avgaserna", "Kyler motorn", "Laddar batteriet"], a: 1, why: "Katalysatorn gör om giftiga gaser till mindre farliga. Den fungerar bäst när den är varm." },
  { id: "e31", cat: "miljo", q: "Vad gör ett start-stopp-system?", opts: ["Bromsar bilen automatiskt", "Startar bilen med mobilen", "Stoppar bilen vid fortkörning", "Stänger av motorn när bilen står still, t.ex. vid rödljus"], a: 3, why: "Motorn stängs av när du står still och startar när du ska köra. Det sparar bränsle och minskar avgaser." },
  { id: "e32", cat: "miljo", q: "Vad är en laddhybrid?", opts: ["En bil som bara går på el", "En bil som kan köras både på el och på bensin eller diesel, och som kan laddas från elnätet", "En bil som går på gas", "En bil utan motor"], a: 1, why: "En laddhybrid har både elmotor och förbränningsmotor. Ladda ofta så kör du mer på el." },

  // ───────── Bilen & körkortet ─────────
  { id: "f1", cat: "fordon", q: "Vilket minsta mönsterdjup gäller för vinterdäck när vinterdäckskravet gäller?", opts: ["1,6 mm", "3 mm", "5 mm", "8 mm"], a: 1, why: "Vinterdäck ska ha minst 3 mm mönsterdjup. Sommardäck minst 1,6 mm – men mer är säkrare." },
  { id: "f2", cat: "fordon", q: "Under vilken period gäller vinterdäckskrav vid vinterväglag?", opts: ["1 oktober – 30 april", "1 december – 31 mars", "1 november – 1 april", "Hela året"], a: 1, why: "Vinterdäckskravet gäller 1 december – 31 mars när det är vinterväglag." },
  { id: "f3", cat: "fordon", q: "När får du normalt köra med dubbdäck?", opts: ["1 oktober – 15 april (och annars vid vinterväglag)", "Hela året", "Bara i december", "1 januari – 1 mars"], a: 0, why: "Dubbdäck får användas 1 oktober – 15 april, och även andra tider om det är eller kan bli vinterväglag." },
  { id: "f4", cat: "fordon", q: "Vilken belysning ska vara tänd när du kör på dagen?", opts: ["Ingen", "Halvljus eller varselljus", "Dimljus", "Parkeringsljus"], a: 1, why: "Du ska alltid ha halvljus eller varselljus tänt när du kör. När det är mörkt eller dålig sikt krävs halvljus (inte bara varselljus)." },
  { id: "f5", cat: "fordon", q: "Hur tung får en personbil vara (totalvikt) för att du ska få köra den med B-körkort?", opts: ["2 000 kg", "3 500 kg", "5 000 kg", "7 500 kg"], a: 1, why: "B-körkort gäller personbil och lätt lastbil med totalvikt högst 3 500 kg." },
  { id: "f6", cat: "fordon", q: "Hur tungt släp (totalvikt) får du alltid dra med B-körkort?", opts: ["Högst 750 kg", "Högst 1 500 kg", "Högst 3 500 kg", "Hur tungt som helst"], a: 0, why: "Ett lätt släp på högst 750 kg får du alltid dra. Tyngre släp går om bil + släp tillsammans väger högst 3 500 kg (eller 4 250 kg med B96)." },
  { id: "f7", cat: "fordon", q: "Hur gammal måste du vara för att få övningsköra personbil?", opts: ["15 år", "16 år", "17 år", "18 år"], a: 1, why: "Du får övningsköra från 16 år om du har körkortstillstånd. Körkort får du ta från 18 år." },
  { id: "f8", cat: "fordon", q: "Vad krävs för att vara privat handledare vid övningskörning?", opts: ["Bara att ha körkort", "Minst 24 år, körkort i minst 5 av de senaste 10 åren, introduktionsutbildning och godkännande", "Vara förälder", "Ha gått på trafikskola"], a: 1, why: "Handledaren ska vara minst 24 år, ha haft körkort minst 5 av de senaste 10 åren, ha gått introduktionsutbildning och ha ett handledarskap godkänt av Transportstyrelsen." },
  { id: "f9", cat: "fordon", q: "Hur många frågor måste du ha rätt på för att klara kunskapsprovet?", opts: ["40 av 65", "52 av 65", "60 av 70", "Alla"], a: 1, why: "Kunskapsprovet har 70 frågor varav 65 räknas. Du behöver minst 52 rätt. Du har 50 minuter på dig." },
  { id: "f10", cat: "fordon", q: "Ett barn är kortare än 135 cm. Hur ska barnet åka?", opts: ["Med vanligt bälte", "I bilbarnstol eller på bälteskudde/bältesstol anpassad för barnet", "I knät på en vuxen", "Det spelar ingen roll"], a: 1, why: "Barn under 135 cm ska använda särskild skyddsanordning, t.ex. bilbarnstol eller bältesstol. Bakåtvänd stol får inte sitta framför en aktiverad krockkudde." },
  { id: "f11", cat: "fordon", q: "Vem ansvarar för att passagerare under 15 år använder bälte?", opts: ["Barnet själv", "Föraren", "Föräldrarna, även om de inte är med", "Ingen"], a: 1, why: "Föraren ansvarar för att passagerare under 15 år använder bälte eller annan skyddsanordning." },
  { id: "f12", cat: "fordon", q: "När får du använda bakre dimljus?", opts: ["Alltid i mörker", "Bara vid nedsatt sikt pga t.ex. dimma eller kraftigt snöfall", "När det regnar lite", "När du parkerar"], a: 1, why: "Bakre dimljus är så starkt att det bländar. Använd bara när sikten är kraftigt nedsatt." },
  { id: "f13", cat: "fordon", q: "Vad visar en röd varningslampa för oljetryck på instrumentpanelen?", opts: ["Att det är dags för service om ett år", "Att du ska stanna så snart det är säkert och stänga av motorn", "Att oljan är för varm att dricka", "Inget viktigt"], a: 1, why: "Rött = allvarligt. Lågt oljetryck kan förstöra motorn snabbt. Stanna säkert och kontrollera." },
  { id: "f14", cat: "fordon", q: "Vad behöver du innan du får börja övningsköra?", opts: ["Ett godkänt körprov", "En egen bil", "Inget alls", "Ett körkortstillstånd"], a: 3, why: "Du söker körkortstillstånd hos Transportstyrelsen. I ansökan ingår bland annat en hälsodeklaration och ett synintyg." },
  { id: "f15", cat: "fordon", q: "Vad krävs för att du ska få övningsköra privat, t.ex. med en förälder?", opts: ["Att du har klarat kunskapsprovet", "Att bilen är ny", "Att både du och handledaren har gått en introduktionsutbildning", "Att ni bara kör på natten"], a: 2, why: "Både eleven och handledaren måste gå introduktionsutbildning innan handledaren kan bli godkänd." },
  { id: "f16", cat: "fordon", q: "Vad är riskutbildning del 2?", opts: ["Körning på halkbana där du lär dig om fart, väglag och risker", "En utbildning om alkohol och droger", "Ett skriftligt prov", "En kurs i bilmekanik"], a: 0, why: "Del 1 handlar om alkohol, droger, trötthet och riskfyllda beteenden. Del 2 är på halkbana. Båda måste vara klara före proven." },
  { id: "f17", cat: "fordon", q: "Hur länge gäller ett körkortstillstånd?", opts: ["1 år", "2 år", "5 år", "Hela livet"], a: 2, why: "Körkortstillståndet gäller i 5 år. Hinner du inte ta körkort under den tiden behöver du söka nytt." },
  { id: "f18", cat: "fordon", q: "Hur länge gäller själva körkortskortet för B innan det måste förnyas?", opts: ["2 år", "5 år", "10 år", "Hela livet"], a: 2, why: "Körkortskortet gäller i 10 år. Sedan förnyar du det med nytt foto." },
  { id: "f19", cat: "fordon", q: "Du har klarat kunskapsprovet. Inom vilken tid måste du klara körprovet?", opts: ["2 veckor", "2 månader", "1 år", "Det finns ingen tidsgräns"], a: 1, why: "Båda proven måste vara godkända inom 2 månader från det första godkända provet. Annars måste du göra om det." },
  { id: "f20", cat: "fordon", q: "Vad ger behörighet B96?", opts: ["Rätt att köra buss", "Rätt att köra bil med tyngre släp – bil och släp får tillsammans väga högst 4 250 kg", "Rätt att köra motorcykel", "Rätt att köra lastbil över 3 500 kg"], a: 1, why: "Med B96 får bil och släp tillsammans ha en totalvikt på högst 4 250 kg." },
  { id: "f21", cat: "fordon", q: "Hur tungt släp (totalvikt) får du dra med behörighet BE?", opts: ["Högst 750 kg", "Högst 2 000 kg", "Högst 3 500 kg", "Hur tungt som helst"], a: 2, why: "Med BE får du dra ett släp med totalvikt på högst 3 500 kg efter en bil som du får köra med B." },
  { id: "f22", cat: "fordon", q: "Släpet är bredare än bilen och du ser inte bakåt i backspeglarna. Vad gäller?", opts: ["Det gör inget", "Du måste ha extra eller förlängda backspeglar", "Du kör bara med varningsblinkers", "Du tittar ut genom fönstret"], a: 1, why: "Du måste kunna se bakåt. Använd förlängda backspeglar om släpet skymmer sikten." },
  { id: "f23", cat: "fordon", q: "Vem ansvarar för att lasten är ordentligt säkrad?", opts: ["Den som har packat", "Föraren", "Ägaren av lasten", "Ingen"], a: 1, why: "Föraren ansvarar för att lasten inte kan glida, falla av eller skada någon. Spänn fast den ordentligt." },
  { id: "f24", cat: "fordon", q: "Lasten sticker ut mer än 1 meter bakom bilen. Vad gäller?", opts: ["Inget särskilt", "Det är alltid förbjudet", "Du ska köra med helljus", "Den ska märkas ut så att den syns, t.ex. med en flagga eller skylt"], a: 3, why: "Last som sticker ut mer än en meter bakåt måste märkas så att andra ser den. I mörker krävs också lykta." },
  { id: "f25", cat: "fordon", q: "När ska en ny personbil besiktas första gången?", opts: ["Efter 1 år", "Efter 5 år", "Efter 3 år", "Aldrig"], a: 2, why: "En ny personbil besiktas första gången efter 3 år, sedan efter 2 år och därefter varje år." },
  { id: "f26", cat: "fordon", q: "Vad händer om bilen inte besiktas i tid?", opts: ["Inget", "Bilen får körförbud", "Du får en guldstjärna", "Bilen avregistreras direkt"], a: 1, why: "Missar du besiktningen får bilen körförbud. Då får du bara köra den till besiktning." },
  { id: "f27", cat: "fordon", q: "Vilken försäkring måste en bil i trafik alltid ha?", opts: ["Helförsäkring", "Reseförsäkring", "Trafikförsäkring", "Ingen"], a: 2, why: "Trafikförsäkring är obligatorisk. Den betalar bland annat för personskador vid olyckor." },
  { id: "f28", cat: "fordon", q: "Var får en bakåtvänd bilbarnstol INTE sitta?", opts: ["I baksätet", "Bakom föraren", "I framsätet framför en aktiverad krockkudde", "I mitten av baksätet"], a: 2, why: "Om krockkudden blåses upp kan barnet skadas allvarligt. Stäng av krockkudden eller sätt stolen i baksätet." },
  { id: "f29", cat: "fordon", q: "Vem ansvarar för att en vuxen passagerare (över 15 år) använder bälte?", opts: ["Föraren", "Passageraren själv", "Bilens ägare", "Polisen"], a: 1, why: "Passagerare som är 15 år eller äldre ansvarar själva för att använda bälte." },
  { id: "f30", cat: "fordon", q: "Du har dubbdäck på en personbil. Vad gäller?", opts: ["Det räcker med dubbdäck fram", "Det räcker med dubbdäck bak", "Alla hjul ska ha dubbdäck", "Du får blanda som du vill"], a: 2, why: "Har bilen dubbdäck ska det sitta dubbdäck på alla hjul. Då blir greppet lika runt om." },
  { id: "f31", cat: "fordon", q: "Du övningskör privat med en handledare. Hur ska bilen vara märkt?", opts: ["Med en skylt där det står ÖVNINGSKÖRNING", "Med varningsblinkers på", "Med en gul lampa på taket", "Ingen märkning behövs"], a: 0, why: "Bilen ska ha en skylt med texten ÖVNINGSKÖRNING så att andra förstår att en elev kör." },
  { id: "f32", cat: "fordon", q: "Du är handledare vid övningskörning och har druckit alkohol. Vad gäller?", opts: ["Handledaren räknas som förare och kan dömas för rattfylleri", "Det spelar ingen roll, eleven kör", "Det är okej upp till 1,0 promille", "Bara eleven måste vara nykter"], a: 0, why: "Handledaren räknas som förare vid övningskörning. Därför måste även handledaren vara nykter." },
  { id: "f33", cat: "fordon", q: "Du gör körprovet i en bil med automatlåda. Vad gäller då?", opts: ["Du får köra alla bilar", "Du måste göra om provet", "Körkortet får ett villkor om att du bara får köra automatväxlad bil", "Du får bara köra elbil"], a: 2, why: "Gör du körprovet med automat får körkortet villkoret kod 78. Då får du bara köra bil med automatlåda." },
];
